import json, math, os, time
import numpy as np
import rcb_robolab as rb

# Shrink the three observation cameras before environment construction; trajectory generation
# uses ground-truth object poses and does not need full-resolution images.
_original_launch = rb._launch_app
def _launch_with_small_cameras():
    app = _original_launch()
    import robolab.core.environments.runtime as runtime
    _original_create_env = runtime.create_env
    def _create_small_env(scene, *args, **kwargs):
        if not isinstance(scene, str):
            seen = set()
            def shrink(obj):
                if id(obj) in seen:
                    return
                seen.add(id(obj))
                if hasattr(obj, "width") and hasattr(obj, "height"):
                    try:
                        if int(obj.width) > 320 or int(obj.height) > 240:
                            print("SHRINK CAMERA", type(obj).__name__, obj.width, obj.height, flush=True)
                            obj.width = 320; obj.height = 240
                    except Exception:
                        pass
                if hasattr(obj, "__dict__"):
                    for child in vars(obj).values():
                        if isinstance(child, (list, tuple)):
                            for x in child:
                                if hasattr(x, "__dict__"):
                                    shrink(x)
                        elif hasattr(child, "__dict__"):
                            shrink(child)
            shrink(scene.scene)
            try:
                scene.sim.render.rendering_mode = "performance"
            except Exception:
                pass
            try:
                scene.viewer.resolution = (640, 360)
            except Exception:
                pass
        return _original_create_env(scene, *args, **kwargs)
    runtime.create_env = _create_small_env
    return app
rb._launch_app = _launch_with_small_cameras

s = rb.Session("pick_orange_object", instance="/app/instance.json")
p = s.primitives()
print("STATUS", s.status(), flush=True)
print("EE", s.ee_pose(), "J", s.joint_positions(), flush=True)
print("CLOSING", p["get_finger_closing_dir"](), "TOPQ", p["top_down_quat"](0), flush=True)
for name, val in s.objects().items():
    if name in ("measuring_cups_1", "table", "serving_bowl", "redonion", "tomato_sauce_can"):
        print("OBJECT", name, val, flush=True)
pts = p["get_object_points"]("measuring_cups_1")
print("POINTS", pts.shape, "minmax", np.min(pts,axis=0), np.max(pts,axis=0), flush=True)
