_original_launch = rb._launch_app
def _launch_small():
    app = _original_launch()
    import robolab.core.environments.runtime as rt
    original = rt.create_env
    def create(scene, *args, **kwargs):
        if not isinstance(scene, str):
            seen=set()
            def shrink(o):
                if id(o) in seen:return
                seen.add(id(o))
                if hasattr(o,'width') and hasattr(o,'height'):
                    try:
                        if int(o.width)>320 or int(o.height)>240:o.width=320;o.height=240
                    except Exception:pass
                if hasattr(o,'__dict__'):
                    for v in vars(o).values():
                        if isinstance(v,(list,tuple)):
                            for x in v:
                                if hasattr(x,'__dict__'):shrink(x)
                        elif hasattr(v,'__dict__'):shrink(v)
            shrink(scene.scene)
            try:scene.sim.render.rendering_mode='performance'
            except:pass
        return original(scene,*args,**kwargs)
    rt.create_env=create
    return app
